PRAGMA foreign_keys=ON;
CREATE TABLE allusions(id TEXT PRIMARY KEY,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,pinyin TEXT NOT NULL DEFAULT '',summary TEXT NOT NULL DEFAULT '',meaning TEXT NOT NULL DEFAULT '',story TEXT NOT NULL DEFAULT '',usage_notes TEXT NOT NULL DEFAULT '',search_text TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','review','published','archived')),quality_level INTEGER NOT NULL DEFAULT 0 CHECK(quality_level BETWEEN 0 AND 3),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,published_at INTEGER);
CREATE INDEX allusions_title_idx ON allusions(title); CREATE INDEX allusions_status_idx ON allusions(status); CREATE INDEX allusions_quality_idx ON allusions(quality_level); CREATE INDEX allusions_updated_idx ON allusions(updated_at);
CREATE TABLE allusion_aliases(id TEXT PRIMARY KEY,allusion_id TEXT NOT NULL REFERENCES allusions(id) ON DELETE CASCADE,alias TEXT NOT NULL,alias_type TEXT NOT NULL DEFAULT 'alternate',created_at INTEGER NOT NULL,UNIQUE(allusion_id,alias)); CREATE INDEX aliases_alias_idx ON allusion_aliases(alias); CREATE INDEX aliases_allusion_idx ON allusion_aliases(allusion_id);
CREATE TABLE works(id TEXT PRIMARY KEY,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,author_text TEXT,dynasty TEXT,description TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE people(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,dynasty TEXT,birth_year INTEGER,death_year INTEGER,summary TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE allusion_sources(id TEXT PRIMARY KEY,allusion_id TEXT NOT NULL REFERENCES allusions(id) ON DELETE CASCADE,work_id TEXT REFERENCES works(id),source_type TEXT NOT NULL,chapter TEXT,original_text TEXT,translation TEXT,note TEXT,reference_note TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL); CREATE INDEX sources_allusion_idx ON allusion_sources(allusion_id); CREATE INDEX sources_work_idx ON allusion_sources(work_id);
CREATE TABLE examples(id TEXT PRIMARY KEY,allusion_id TEXT NOT NULL REFERENCES allusions(id) ON DELETE CASCADE,quote TEXT NOT NULL,author_text TEXT,work_title TEXT,dynasty TEXT,person_id TEXT REFERENCES people(id),work_id TEXT REFERENCES works(id),explanation TEXT,reference_note TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL); CREATE INDEX examples_allusion_idx ON examples(allusion_id);
CREATE TABLE scenarios(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT,parent_id TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT,parent_id TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE tags(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT,parent_id TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE allusion_scenarios(allusion_id TEXT NOT NULL REFERENCES allusions(id) ON DELETE CASCADE,scenario_id TEXT NOT NULL REFERENCES scenarios(id) ON DELETE RESTRICT,relevance INTEGER NOT NULL DEFAULT 50,is_primary INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(allusion_id,scenario_id)); CREATE INDEX as_scenario_idx ON allusion_scenarios(scenario_id);
CREATE TABLE allusion_categories(allusion_id TEXT NOT NULL REFERENCES allusions(id) ON DELETE CASCADE,category_id TEXT NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,PRIMARY KEY(allusion_id,category_id)); CREATE INDEX ac_category_idx ON allusion_categories(category_id);
CREATE TABLE allusion_tags(allusion_id TEXT NOT NULL REFERENCES allusions(id) ON DELETE CASCADE,tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE RESTRICT,PRIMARY KEY(allusion_id,tag_id)); CREATE INDEX at_tag_idx ON allusion_tags(tag_id);
CREATE TABLE allusion_people(allusion_id TEXT NOT NULL REFERENCES allusions(id) ON DELETE CASCADE,person_id TEXT NOT NULL REFERENCES people(id) ON DELETE RESTRICT,role TEXT NOT NULL DEFAULT 'related',sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(allusion_id,person_id,role)); CREATE INDEX ap_person_idx ON allusion_people(person_id);
CREATE TABLE related_allusions(allusion_id TEXT NOT NULL REFERENCES allusions(id) ON DELETE CASCADE,related_allusion_id TEXT NOT NULL REFERENCES allusions(id) ON DELETE CASCADE,relation_type TEXT NOT NULL,score INTEGER NOT NULL DEFAULT 50,note TEXT,PRIMARY KEY(allusion_id,related_allusion_id,relation_type)); CREATE INDEX related_target_idx ON related_allusions(related_allusion_id);
CREATE TABLE entity_revisions(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,snapshot_json TEXT NOT NULL,changed_by TEXT,created_at INTEGER NOT NULL); CREATE INDEX revisions_entity_idx ON entity_revisions(entity_type,entity_id);
CREATE TABLE ai_runs(id TEXT PRIMARY KEY,task_type TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,provider TEXT,model TEXT,prompt_version TEXT,input_hash TEXT,input_json TEXT NOT NULL,output_json TEXT,status TEXT NOT NULL DEFAULT 'pending',error TEXT,created_at INTEGER NOT NULL,completed_at INTEGER);
CREATE TABLE ai_suggestions(id TEXT PRIMARY KEY,ai_run_id TEXT NOT NULL REFERENCES ai_runs(id),entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,field_name TEXT NOT NULL,suggested_value TEXT NOT NULL,confidence REAL,status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL,reviewed_at INTEGER); CREATE INDEX suggestions_entity_idx ON ai_suggestions(entity_type,entity_id);
CREATE TABLE import_batches(id TEXT PRIMARY KEY,name TEXT NOT NULL,source TEXT,status TEXT NOT NULL DEFAULT 'pending',total_count INTEGER NOT NULL DEFAULT 0,success_count INTEGER NOT NULL DEFAULT 0,error_count INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,completed_at INTEGER);
CREATE TABLE import_items(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES import_batches(id),raw_json TEXT NOT NULL,matched_allusion_id TEXT REFERENCES allusions(id),status TEXT NOT NULL DEFAULT 'pending',error TEXT,created_at INTEGER NOT NULL); CREATE INDEX import_items_batch_idx ON import_items(batch_id);
CREATE TABLE user(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,email_verified INTEGER NOT NULL DEFAULT 0,image TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE session(id TEXT PRIMARY KEY,expires_at INTEGER NOT NULL,token TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,ip_address TEXT,user_agent TEXT,user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE); CREATE INDEX session_user_idx ON session(user_id);
CREATE TABLE account(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,provider_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE,access_token TEXT,refresh_token TEXT,id_token TEXT,access_token_expires_at INTEGER,refresh_token_expires_at INTEGER,scope TEXT,password TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL); CREATE INDEX account_user_idx ON account(user_id);
CREATE TABLE verification(id TEXT PRIMARY KEY,identifier TEXT NOT NULL,value TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER,updated_at INTEGER);
